    r'^\d{3}-\d{3}$'
]

def detect(cell):
    if re.match(r'^\d{6,}$', cell) or cell in ['11000', '78310', '28806']:
        return True
    for pattern in CLEAN_PATTERNS:
        if re.match(pattern, cell):
            return False
    return True

def corrupt(cell):
    if re.match(CLEAN_PATTERNS[0], cell):  # \d{4}
        cell = cell + '0'  # Add an extra digit to make it dirty
    elif re.match(CLEAN_PATTERNS[1], cell):  # \d{5}
        random_point = random.randint(0, 4)
        cell = cell[:random_point] + 'x' + cell[random_point+1:]  # Replace a random digit with 'x'
    elif re.match(CLEAN_PATTERNS[2], cell):  # [A-Za-z]{1,2}\d[A-Za-z] \d[A-Za-z]{2}
