import re
import random

def corrupt(cell):
    # List of potential transformations to make clean cells dirty
    transformations = [
        lambda x: x.upper(),  # Convert to uppercase
        lambda x: x.lower(),  # Convert to lowercase
        lambda x: x.title(),  # Capitalize the first letter of each word
        lambda x: ' '.join(word[0].upper() + word[1:] for word in x.split()),  # Capitalize all words with added space if not already there
        lambda x: x.replace(' ', ''),  # Remove spaces
        lambda x: x.replace(' ', '  ') if ' ' in x else x.replace('-', ' '),  # Add extra spaces inconsistently
        lambda x: x.replace('United', 'Unitd'),  # Misspell common words
        lambda x: x.replace('States', 'Sttes'),  # Misspell common words
        lambda x: ''.join(random.sample(x, len(x))),  # Randomly shuffle characters in the string
        lambda x: x[0] + ''.join(random.sample(x[1:], len(x)-1)),  # Fix first letter, shuffle the rest
    ]

    if re.match(r'^France$', cell):
        return random.choice([cell.lower(), cell.title(), cell.upper()])

    if re.match(r'^United States$', cell):
        return random.choice([cell.lower(), cell.replace('United', 'Unitd'), cell.replace('States', 'Sttes')])

    if re.match(r'^US$', cell) or re.match(r'^DE$', cell) or re.match(r'^FR$', cell) or re.match(r'^CH$', cell):
        return cell + ' '  # Add a space

    if re.match(r'^Canada$', cell):
        return cell.title()  # Capitalize the first letter

    if re.match(r'^Россия$', cell):
        return cell + ' '  # Add a space

    if re.match(r'^ITALIA$', cell):
        return cell + ' '  # Add a space

    if re.match(r'^UNITED\s+STATES$', cell):
        return cell.lower()  # Convert to lowercase

    if re.match(r'^UK$', cell):
        return cell.replace('U', 'V')  # Misspell

    # For countries given as full names (such as Polska for Poland, Lietuva for Lithuania)
    if cell in ['Polska', 'Lietuva']:
        return cell.lower()  # Convert to lowercase

    # Default transformation: choose randomly from all transformations
    return random.choice(transformations)(cell)

